<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\ExceptionalMember;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class ExceptionalMemberController extends Controller{public function index(){return ExceptionalMember::where('published',true)->orderBy('sort_order')->latest()->get();}public function manage(){return ExceptionalMember::orderBy('sort_order')->latest()->get();}public function store(Request $request){$data=$this->validated($request);if($request->hasFile('photo'))$data['photo_url']=Storage::disk('public')->url($request->file('photo')->store('exceptional-members','public'));$data['created_by']=$request->user()->id;$data['updated_by']=$request->user()->id;return response()->json(ExceptionalMember::create($data),201);}public function update(Request $request,ExceptionalMember $exceptionalMember){$data=$this->validated($request,true);if($request->hasFile('photo')){$this->removePhoto($exceptionalMember->photo_url);$data['photo_url']=Storage::disk('public')->url($request->file('photo')->store('exceptional-members','public'));}$data['updated_by']=$request->user()->id;$exceptionalMember->update($data);return $exceptionalMember->fresh();}public function destroy(ExceptionalMember $exceptionalMember){$this->removePhoto($exceptionalMember->photo_url);$exceptionalMember->delete();return response()->json(['message'=>'Exceptional member removed.']);}private function validated(Request $r,bool $partial=false):array{$required=$partial?'sometimes':'required';return $r->validate(['user_id'=>'nullable|exists:users,id','name'=>"$required|string|max:120",'graduating_year'=>'nullable|integer|min:1900|max:2100','title'=>"$required|string|max:180",'citation'=>"$required|string|max:3000",'photo'=>'sometimes|image|mimes:jpeg,jpg,png,webp|max:5120','sort_order'=>'sometimes|integer|min:0','published'=>'sometimes|boolean']);}private function removePhoto(?string $url):void{if($url&&str_contains($url,'/storage/'))Storage::disk('public')->delete(str($url)->after('/storage/')->toString());}}
